fn solve(coins: Vec<i8>) -> i8 {
    // Sum up the five coin values in a wider integer type to avoid overflow.
    let sum: i16 = coins.iter().map(|&c| c as i16).sum();

    // Check that the sum is strictly positive and divisible by 5.
    if sum > 0 && sum % 5 == 0 {
        // Safe to cast back to i8, since (sum/5) ≤ 100.
        (sum / 5) as i8
    } else {
        -1
    }
}

