        assert_eq!(solve(vec![1, 2, 3, 4, 5]), 3);   // sum = 15, avg = 3
        assert_eq!(solve(vec![0, 0, 0, 0, 5]), 1);   // sum = 5, avg = 1
        assert_eq!(solve(vec![0, 0, 0, 0, 0]), -1);  // sum = 0 → invalid
        assert_eq!(solve(vec![1, 1, 1, 1, 2]), -1);  // sum = 6 → not divisible by 5
        assert_eq!(solve(vec![100, 100, 100, 100, 100]), 100); // sum = 500, avg = 100
